const b = $input.first().json.body || $input.first().json || {};
const msg = String(b.message || b.query || '').trim();
const groqKey = $env.GROQ_API_KEY || '';
const elevenKey = $env.ELEVENLABS_API_KEY || '';
const voiceId = $env.ELEVENLABS_VOICE_ID || 'pFZP5JQG7iQjIQuC4Bku';
const brand = $env.BRAND_NAME || 'Tradesejon';

let reply = `${brand} AIOS processed: "${msg}"`;
if (groqKey && msg) {
  const r = await fetch('https://api.groq.com/openai/v1/chat/completions', {
    method: 'POST', headers: { 'Authorization': `Bearer ${groqKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'llama-3.3-70b-versatile',
      messages: [
        { role: 'system', content: `You are ${brand} AIOS Command Center Assistant. Answer helpfully and concisely without fabricating actions or data.` },
        { role: 'user', content: msg }
      ]
    })
  }).then(res => res.json()).catch(() => ({}));
  if (r.choices?.[0]?.message?.content) reply = r.choices[0].message.content;
}

let audioBase64 = null;
if ((b.voice || b.returnVoice) && elevenKey) {
  try {
    const ttsRes = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${voiceId}`, {
      method: 'POST', headers: { 'xi-api-key': elevenKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({ text: reply.slice(0, 400), model_id: 'eleven_multilingual_v2' })
    });
    if (ttsRes.ok) audioBase64 = Buffer.from(await ttsRes.arrayBuffer()).toString('base64');
  } catch (e) {}
}

return [{ json: { ok: true, reply, voice_enabled: Boolean(audioBase64), audioBase64 } }];
